// For the #WCCChallenge, and genuary2026, day 26, theme "recursive grids."

function setup() {
	createCanvas(windowHeight * 0.95, windowHeight * 0.95);
	fill('#FFC00020');
	shift = createVector(0, 0);
	rectMode(CENTER);
	noCursor();
}

function drawSquare(x, y, d, s) {
	if (d < height / 60) return;
	push();
	translate(x, y);
	let reach = atan2(y - shift.y, x - shift.x);
	rect(0, 0, d, d);
	pop();
	drawSquare(x - cos(reach) * s / 2, y - sin(reach) * s / 2, (s - 1) * d / s, s);
}

function draw() {
	background(255);
	translate(width / 2, height / 2);
	shift.lerp(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width / 2, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height / 2), 0.1);
	for (let y of [-0.3 * height, 0, 0.3 * height]) {
		for (let x of [-0.3 * height, 0, 0.3 * height]) {
			drawSquare(x, y, 0.29 * height, 10);
		}
	}
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
